  // [data-pad]: se puede pulsar aunque no tenga cursor de mano (los Pokémon que aún no tienes).
  const NATIVE = 'button, a[href], input, select, textarea, summary, label[for], [data-pad]';
  let rumbleWarned = false, padWarned = false;
