/* js/ui/login.js */
/* ============ login.js — inicio: entrar, crear cuenta o invitado ============ */
G.LoginUI = (() => {
  const $ = G.UI.$;
  let mode = 'login';

  function init() {
    document.querySelectorAll('#scr-login .tab').forEach(t => {
      t.onclick = () => setMode(t.dataset.tab);
    });
    $('login-form').onsubmit = async e => {
      e.preventDefault();
      $('login-err').textContent = '';
      $('btn-auth').disabled = true;
      const fn = mode === 'login' ? G.DB.login : G.DB.register;
      const r = await fn($('f-user').value, $('f-pass').value);
      $('btn-auth').disabled = false;
      if (!r.ok) { $('login-err').textContent = r.error; return; }
      $('f-pass').value = '';
      G.Flow.afterLogin();
    };
    $('btn-guest').onclick = () => { G.DB.playAsGuest(); G.Flow.afterLogin(); };
    $('f-forgot').onclick = e => {
      e.preventDefault();
      $('login-err').textContent = '';
      $('forgot-note').classList.toggle('hidden');
    };
    // Vincular Gmail para poder recuperar la cuenta (ver offerRecovery).
    $('rec-link').onclick = async () => {
      $('rec-err').textContent = '';
      const password=await G.UI.requestPassword(); if(password===null) return;
      $('rec-link').disabled = true;
      const r = await G.DB.linkGoogle(password);
      $('rec-link').disabled = false;
      if (!r.ok) { $('rec-err').textContent = r.error; return; }
      if(r.redirecting) return;
      $('scr-recover').classList.add('hidden');
      G.UI.toast('¡Gmail vinculado! Si olvidas la contraseña, entra con Google.', 4500);
    };
    $('rec-later').onclick = () => $('scr-recover').classList.add('hidden');
    $('rec-never').onclick = () => {
      try { localStorage.setItem('ps.recover.no.' + G.DB.fb.uid, '1'); } catch (e) { /* nada */ }
      $('scr-recover').classList.add('hidden');
    };
    $('btn-google').onclick = async () => {
      $('login-err').textContent = '';
      $('btn-google').disabled = true;
      const r = await G.DB.loginWithGoogle();
      $('btn-google').disabled = false;
      if (!r.ok) { $('login-err').textContent = r.error; return; }
      if(r.redirecting) return;
      G.Flow.afterLogin();
    };
  }

  /**
   * Al entrar (o recién creada la cuenta) con nombre y contraseña, si aún no
   * hay Gmail vinculado: "¿te da miedo perder tu cuenta?". Una vez por sesión,
   * hasta que lo vincule o diga que no le vuelvan a preguntar.
   */
  let offered = false;
  function offerRecovery() {
    if (!G.Backend.googleEnabled || offered || G.DB.mode !== 'cloud' || !G.DB.fb || !G.DB.nameAccount || G.DB.hasGoogle) return;
    try { if (localStorage.getItem('ps.recover.no.' + G.DB.fb.uid)) return; } catch (e) { /* nada */ }
    offered = true;
    $('rec-err').textContent = '';
    $('scr-recover').classList.remove('hidden');
  }

  /** Explica dónde se guarda la partida según el modo de la base de datos. */
  function modeNote() {
    if (G.DB.mode === 'cloud') return 'Tu partida se guarda en la nube: entra desde cualquier ordenador. Como invitado no se guarda.';
    const why = G.DB.localReason === 'file'
      ? 'Abierto desde un archivo: la partida sólo se guarda en este navegador. Para guardar en la nube, juega en la versión publicada.'
      : G.DB.localReason === 'host'
        ? 'Esta no es la web oficial: la partida sólo se guarda en este navegador. El juego oficial y gratis está en pokesurvivor.com.'
      : G.DB.localReason === 'config'
        ? 'Nube sin configurar: la partida sólo se guarda en este navegador.'
        : 'No se pudo conectar con la nube: la partida sólo se guarda en este navegador.';
    return why;
  }

  function setMode(m) {
    mode = m;
    document.querySelectorAll('#scr-login .tab').forEach(t => t.classList.toggle('on', t.dataset.tab === m));
    $('btn-auth').textContent = m === 'login' ? 'Entrar' : 'Crear cuenta';
    $('f-pass').autocomplete = m === 'login' ? 'current-password' : 'new-password';
    $('login-err').textContent = '';
  }

  function open() {
    G.UI.chrome(false);
    G.UI.show('scr-login');
    if (!G.DB.storageOk) $('login-err').textContent = 'Este navegador no deja guardar datos: juega como invitado.';
    $('btn-google').classList.toggle('hidden', !G.Backend.googleEnabled);
    $('login-mode').textContent = modeNote();
    setTimeout(() => $('f-user').focus(), 50);
  }

  return { init, open, offerRecovery };
})();

;
/* js/ui/test.js */
/* ============ test.js — test de personalidad y elección de compañero ============ */
G.TestUI = (() => {
  const $ = G.UI.$;
  let idx = 0, scores = {}, result = null, picked = null;

  function init() {
    $('res-ok').onclick = () => choose(result.dex);
    $('res-other').onclick = openStarters;
    $('starter-back').onclick = () => G.UI.show('scr-result');
    $('starter-ok').onclick = () => { if (picked) choose(picked); };
  }

  function start() {
    idx = 0; scores = {}; result = null;
    G.UI.chrome(false);
    G.UI.show('scr-test');
    render();
  }

  function render() {
    const Q = G.PERSONALITY_TEST;
    const q = Q[idx];
    $('test-bar').style.width = (idx / Q.length * 100) + '%';
    $('test-count').textContent = `Pregunta ${idx + 1} de ${Q.length}`;
    $('test-q').textContent = q.q;
    const box = $('test-a');
    box.innerHTML = '';
    q.a.forEach(a => {
      const b = document.createElement('button');
      b.className = 'answer';
      b.dataset.sfx = 'select';
      b.textContent = a.t;
      b.onclick = () => answer(a);
      box.appendChild(b);
    });
  }

  function answer(a) {
    for (const k in a.p) scores[k] = (scores[k] || 0) + a.p[k];
    idx++;
    if (idx < G.PERSONALITY_TEST.length) render();
    else showResult();
  }

  function showResult() {
    result = G.personalityResult(scores);
    const mon = G.DEX_BY[result.dex];
    $('res-trait').textContent = result.trait.charAt(0).toUpperCase() + result.trait.slice(1);
    $('res-text').textContent = G.TRAIT_TEXT[result.trait] || '';
    $('res-name').textContent = mon.name;
    G.UI.sprite($('res-stage'), mon.dex, { lively: true, scale: 4, hero: true });
    $('res-stage').style.setProperty('--stage-c', G.U.TYPE_COLOR[mon.types[0]]);
    G.UI.show('scr-result');
  }

  /** Abre la rejilla de starters. `fromMenu` = cambiar compañero inicial más tarde. */
  function openStarters() {
    picked = null;
    $('starter-ok').disabled = true;
    $('starter-info').textContent = 'Selecciona un Pokémon';
    const grid = $('starter-grid');
    grid.innerHTML = '';
    for (const s of G.STARTERS) {
      const mon = G.DEX_BY[s.dex];
      const cell = document.createElement('div');
      cell.className = 'cell' + (result && s.dex === result.dex ? ' on' : '');
      cell.appendChild(G.UI.spriteCanvas(s.dex, 92, 80, { scale: 2 }));
      cell.insertAdjacentHTML('beforeend', `<b>${mon.name}</b>`);
      cell.onclick = () => {
        grid.querySelectorAll('.cell').forEach(c => c.classList.remove('on'));
        cell.classList.add('on');
        picked = s.dex;
        const mv = G.Moves.BY_ID[s.start];
        $('starter-info').innerHTML = `${G.UI.typeChips(mon.types)} ${G.Icons.html('move:' + s.start, 16)} ${mv.name} · ${s.traits.join(', ')}`;
        $('starter-ok').disabled = false;
      };
      if (result && s.dex === result.dex) { picked = s.dex; $('starter-ok').disabled = false; }
      grid.appendChild(cell);
    }
    G.UI.show('scr-starters');
  }

  function choose(dex) {
    const save = G.DB.save;
    save.starter = dex;
    save.partner = dex;
    save.personality = result ? { trait: result.trait, scores } : null;
    G.DB.grant(dex, 'starter');
    G.DB.commit();
    G.UI.toast('¡' + G.DEX_BY[dex].name + ' se une a ti!');
    G.Flow.goMenu();
  }

  return { init, start };
})();

